    __global__ void colorKernel(const PtrStepSz<unsigned char> labels, const uchar4* map, PtrStep<uchar4> output)
    {
      int x = threadIdx.x + blockIdx.x * blockDim.x;
      int y = threadIdx.y + blockIdx.y * blockDim.y;

      if (x < labels.cols && y < labels.rows)
      {
        int l = labels.ptr(y)[x];
        output.ptr(y)[x] = map[l];
      }
    }

    __global__ void mixedColorKernel(const PtrStepSz<unsigned char> labels, const uchar4* map, PtrStepSz<uchar4> rgba, PtrStep<uchar4> output)
    {
      int x = threadIdx.x + blockIdx.x * blockDim.x;
      int y = threadIdx.y + blockIdx.y * blockDim.y;

      if (x < labels.cols && y < labels.rows)
      {        
        uchar4 c = rgba.ptr(y)[x];

        int l = labels.ptr(y)[x];
        if (l != 8) // RHip but should be background
          c = map[l];

        output.ptr(y)[x] = c;
      }
    }
  }
